class NetworkDiagram(Flowable):
    def __init__(self): super().__init__(); self.width=170*mm; self.height=73*mm
    def draw_box(self,x,y,w,h,title,sub,color):
        c=self.canv;c.setFillColor(colors.white);c.setStrokeColor(color);c.setLineWidth(1.5);c.roundRect(x,y,w,h,7,fill=1,stroke=1);c.setFillColor(color);c.setFont('AtlasBold',10);c.drawCentredString(x+w/2,y+h-16,title);c.setFillColor(MUTED);c.setFont('Atlas',7.5)
        for i,line in enumerate(sub):c.drawCentredString(x+w/2,y+h-29-i*10,line)
    def draw(self):
        c=self.canv;c.setStrokeColor(BLUE);c.setLineWidth(2)
        sx=57*mm;sy=42*mm;sw=56*mm;sh=25*mm
        self.draw_box(sx,sy,sw,sh,'PC SERVIDOR',['IIS + Atlas POS','MySQL 8.4','Puerto 8080'],BLUE)
        boxes=[(4,4,'CAJA 1'),(59,4,'CAJA 2'),(114,4,'CAJA N')]
        for x,y,t in boxes:
            self.draw_box(x*mm,y*mm,48*mm,24*mm,t,['Navegador + Atlas Agent','Báscula / impresora / cajón'],TEAL)
            c.line(sx+sw/2,sy,x*mm+24*mm,(y+24)*mm)
        c.setFillColor(PALE);c.roundRect(35*mm,31*mm,100*mm,7*mm,3,fill=1,stroke=0);c.setFillColor(INK);c.setFont('AtlasBold',8);c.drawCentredString(85*mm,33.5*mm,'RED PRIVADA - inventario y ventas centralizados')

class StepGraphic(Flowable):
    def __init__(self,items): super().__init__();self.items=items;self.width=170*mm;self.height=32*mm
    def draw(self):
        c=self.canv;n=len(self.items);gap=4*mm;w=(self.width-gap*(n-1))/n
        for i,(num,title,sub,color) in enumerate(self.items):
            x=i*(w+gap);c.setFillColor(color);c.circle(x+7*mm,22*mm,5*mm,fill=1,stroke=0);c.setFillColor(colors.white);c.setFont('AtlasBold',9);c.drawCentredString(x+7*mm,20.5*mm,str(num));c.setFillColor(INK);c.setFont('AtlasBold',8);c.drawString(x,12*mm,title);c.setFillColor(MUTED);c.setFont('Atlas',6.8);c.drawString(x,7*mm,sub[:29]);
            if i<n-1:c.setStrokeColor(colors.HexColor('#BFCBE0'));c.line(x+w,22*mm,x+w+gap-2,22*mm)

