def header_footer(canvas,doc):
    canvas.saveState();canvas.setFillColor(NAVY);canvas.rect(0,letter[1]-12*mm,letter[0],12*mm,fill=1,stroke=0);canvas.setFillColor(colors.white);canvas.setFont('AtlasBold',8);canvas.drawString(18*mm,letter[1]-8*mm,'ATLAS POS - MANUAL DE INSTALACIÓN');canvas.setFillColor(MUTED);canvas.setFont('Atlas',7);canvas.drawRightString(letter[0]-18*mm,8*mm,f'Página {doc.page}');canvas.restoreState()
def p(text,style='BodyA'):return Paragraph(text,styles[style])
def callout(title,text,color=PALE):
    t=Table([[p(title,'CallA')],[p(text,'BodyA')]],colWidths=[170*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),color),('BOX',(0,0),(-1,-1),.7,BLUE),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return t
def bullets(items):return [p('• '+x) for x in items]
def checklist(rows):
    data=[[p('✓','CallA'),p(x)] for x in rows];t=Table(data,colWidths=[9*mm,161*mm]);t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,0),(-1,-1),[colors.white,colors.HexColor('#F7F9FC')]),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#DDE4EE')),('LEFTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return t

